// import React from "react";

function RatingStars({ value = 0, onChange = () => {}, max = 5 }) {
const buttons = [];

for (let r = 1; r <= max; r++){
  buttons.push(
    <button key = {r} type = "button" onClick = {() => onChange(r)}>
      {r <= value ? "*" : "-"}
    </button>
  )
}
    <div className="stars">
     {buttons}
    </div>
}

export default RatingStars;
